/*
 * qjs_opcodes.c - Opcode tables and dialect detection
 *
 * Single source of truth for QuickJS opcode information across
 * vanilla QuickJS and Frida-QuickJS bytecode variants.
 *
 * The tables themselves are generated by tools/gen_opcodes.sh.
 *
 * Part of the JARONA decompiler.
 */
#include "qjs_opcodes.h"

#include <stdlib.h>
#include <string.h>

/* =========================================================
 * Opcode tables
 * ========================================================= */
#include "qjs_opcodes_vanilla.inc"
#include "qjs_opcodes_frida.inc"

/* =========================================================
 * Global default mode
 * ========================================================= */
static qjs_op_mode_t g_default_mode = QJS_MODE_AUTO;

void qjs_set_default_mode(qjs_op_mode_t mode) { g_default_mode = mode; }
qjs_op_mode_t qjs_get_default_mode(void)      { return g_default_mode; }

const char *qjs_mode_name(qjs_op_mode_t mode) {
    switch (mode) {
        case QJS_MODE_AUTO:    return "auto";
        case QJS_MODE_VANILLA: return "vanilla";
        case QJS_MODE_FRIDA:   return "frida";
        default:               return "unknown";
    }
}

/* =========================================================
 * Get opcode info for a raw byte in a given dialect.
 *
 * Never returns NULL - out of range entries fall through to a static
 * "invalid" record whose size is 0 so that walkers can detect them.
 * ========================================================= */
const qjs_op_info_t *qjs_get_op_info(uint8_t op, qjs_op_mode_t mode) {
    /* The Frida table has 267 entries and therefore covers every possible
     * opcode byte, so no range check is needed for it. */
    if (mode == QJS_MODE_FRIDA)
        return &qjs_op_info_frida[op];
    return &qjs_op_info_vanilla[op];
}

/* =========================================================
 * Byte code walking / dialect detection
 * ========================================================= */

/* Instruction boundary bitmap used while validating jump targets. */
typedef struct {
    uint8_t *bits;
    uint32_t len;
} bc_bits_t;

static int bits_get(const bc_bits_t *b, uint32_t pos) {
    if (pos >= b->len) return 0;
    return (b->bits[pos >> 3] >> (pos & 7)) & 1;
}

static void bits_set(bc_bits_t *b, uint32_t pos) {
    if (pos >= b->len) return;
    b->bits[pos >> 3] |= (uint8_t)(1u << (pos & 7));
}

static uint32_t rd_u16(const uint8_t *p, int be) {
    return be ? ((uint32_t)p[0] << 8 | p[1]) : ((uint32_t)p[1] << 8 | p[0]);
}

static uint32_t rd_u32(const uint8_t *p, int be) {
    if (be)
        return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) |
               ((uint32_t)p[2] << 8) | p[3];
    return ((uint32_t)p[3] << 24) | ((uint32_t)p[2] << 16) |
           ((uint32_t)p[1] << 8) | p[0];
}

/*
 * Decode the jump target of an instruction (relative to the end of the
 * instruction) or return -1 when the opcode has no label operand.
 */
static int64_t label_target(const qjs_op_info_t *info, const uint8_t *bc,
                             uint32_t pc, int be) {
    switch (info->fmt) {
        case QJS_FMT_label8:
            return (int64_t)pc + 1 + (int8_t)bc[pc + 1];
        case QJS_FMT_label16:
            return (int64_t)pc + 1 + (int16_t)rd_u16(bc + pc + 1, be);
        case QJS_FMT_label:
            return (int64_t)pc + 1 + (int32_t)rd_u32(bc + pc + 1, be);
        case QJS_FMT_label_u16:
            return (int64_t)pc + 1 + (int16_t)rd_u16(bc + pc + 1, be);
        case QJS_FMT_atom_label_u8:
            return (int64_t)pc + 5 + (int8_t)bc[pc + 5];
        case QJS_FMT_atom_label_u16:
            return (int64_t)pc + 5 + (int16_t)rd_u16(bc + pc + 5, be);
        default:
            return -1;
    }
}

/*
 * Walk the byte code with a given table and compute a score.
 *
 * Scoring:
 *   +100  the walk lands exactly on bc_len (clean termination)
 *   +40   the walk lands on bc_len but hit invalid/truncated opcodes
 *   -20   the walk did not reach the end
 *   -10   per opcode with size 0 (invalid / out of range slot)
 *   -5    per truncation (instruction would read past the end)
 *   -4    per jump whose target is not an instruction boundary
 *   +2    per temporary opcode (frida dialect only)
 *
 * Returns the score; higher is better.
 */
static int score_walk(const qjs_op_info_t *table,
                      const uint8_t *bc, uint32_t bc_len,
                      int big_endian, int want_temps) {
    bc_bits_t bounds;
    int score = 0;
    int n_invalid = 0;
    int n_trunc = 0;
    int n_temp = 0;
    int n_bad_target = 0;
    uint32_t pos = 0;

    if (bc_len == 0) return 0;

    bounds.len = bc_len + 1;
    bounds.bits = (uint8_t *)calloc((bounds.len + 7) / 8, 1);
    if (!bounds.bits) return -1000;

    /* First pass: mark instruction boundaries and collect statistics. */
    while (pos < bc_len) {
        uint8_t op = bc[pos];
        const qjs_op_info_t *info = &table[op];

        if (info->size == 0 || info->name == NULL) {
            n_invalid++;
            pos++;            /* skip one byte and try to resynchronise */
            continue;
        }

        if (want_temps && op >= QJS_TEMP_OPCODE_FIRST && op <= QJS_TEMP_OPCODE_LAST)
            n_temp++;

        if (pos + info->size > bc_len) {
            n_trunc++;
            break;
        }

        bits_set(&bounds, pos);
        pos += info->size;
    }

    /* Second pass: validate that every jump lands on an instruction. */
    pos = 0;
    while (pos < bc_len) {
        uint8_t op = bc[pos];
        const qjs_op_info_t *info = &table[op];

        if (info->size == 0 || info->name == NULL) { pos++; continue; }
        if (pos + info->size > bc_len) break;

        {
            int64_t tgt = label_target(info, bc, pos, big_endian);
            if (tgt >= 0) {
                if (tgt >= (int64_t)bc_len || !bits_get(&bounds, (uint32_t)tgt))
                    n_bad_target++;
            }
        }

        pos += info->size;
    }

    if (pos == bc_len && n_invalid == 0 && n_trunc == 0)
        score += 100;
    else if (pos == bc_len)
        score += 40;
    else
        score -= 20;

    score -= 10 * n_invalid;
    score -= 5  * n_trunc;
    score -= 4  * n_bad_target;

    /* Temporary opcodes only ever appear in the frida dialect. */
    if (want_temps && n_temp > 0) score += 2 * n_temp;

    free(bounds.bits);
    return score;
}

/* =========================================================
 * Auto-detect the opcode dialect of a byte code body.
 *
 * Strategy:
 *   1. Score the vanilla walk.
 *   2. Score the frida walk.
 *   3. Return frida only when it is clearly better; vanilla is the
 *      common case and must win ties.
 * ========================================================= */
qjs_op_mode_t qjs_detect_op_mode(const uint8_t *bc, uint32_t bc_len,
                                  int big_endian) {
    /* Trivial: empty bodies are always vanilla. */
    if (!bc || bc_len == 0) return QJS_MODE_VANILLA;

    int s_vanilla = score_walk(qjs_op_info_vanilla, bc, bc_len, big_endian, 0);
    int s_frida   = score_walk(qjs_op_info_frida,   bc, bc_len, big_endian, 1);

    /* Prefer vanilla unless frida is clearly better and vanilla is not
     * a clean decode. */
    if (s_frida > s_vanilla && s_vanilla < 90)
        return QJS_MODE_FRIDA;
    return QJS_MODE_VANILLA;
}
